#include <vector>
#include <numeric>

class Solution {
public:
    int countValidSequences(int n) {
        long long MOD = 1000000007;
        if (n <= 0) return 0;
        long long dp[3] = {1, 1, 1};
        for (int step = 1; step < n; ++step) {
            long long n0 = (dp[0] + dp[1]) % MOD;
            long long n1 = (dp[0] + dp[1] + dp[2]) % MOD;
            long long n2 = (dp[1] + dp[2]) % MOD;
            dp[0] = n0; dp[1] = n1; dp[2] = n2;
        }
        return (dp[0] + dp[1] + dp[2]) % MOD;
    }
};

